CREATE TABLE "cliente_tajinaste_plus" (
  "dni_cliente" varchar(9) PRIMARY KEY,
  "nombre" varchar(100) NOT NULL,
  "fecha_nacimiento" date NOT NULL
);

CREATE TABLE "empleados" (
  "dni_empleado" varchar(9) PRIMARY KEY,
  "nombre" varchar(100) NOT NULL,
  "fecha_nacimiento" date NOT NULL,
  "fecha_contratacion" date NOT NULL
);

CREATE TABLE "viveros" (
  "id_vivero" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar(100) UNIQUE NOT NULL,
  "longitud" numeric(9,6) NOT NULL,
  "latitud" numeric(8,6) NOT NULL
);

CREATE TABLE "puestos" (
  "id_puesto" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "dni_empleado" varchar(9) NOT NULL,
  "id_vivero" int NOT NULL,
  "cargo" varchar(80) NOT NULL,
  "fecha_inicio" date NOT NULL,
  "fecha_fin" date
);

CREATE TABLE "zonas" (
  "id_zona" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_vivero" int NOT NULL,
  "nombre" varchar(100) NOT NULL,
  "longitud" numeric(9,6) NOT NULL,
  "latitud" numeric(8,6) NOT NULL
);

CREATE TABLE "tareas" (
  "id_tarea" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_puesto" int NOT NULL,
  "tiempo_estimado_minutos" numeric(7,2) NOT NULL,
  "nombre_tarea" varchar(120) NOT NULL,
  "material_necesario" text NOT NULL
);

CREATE TABLE "productos" (
  "id_producto" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tipo" varchar(60) NOT NULL,
  "nombre" varchar(100) NOT NULL,
  "precio" numeric(10,2) NOT NULL
);

CREATE TABLE "pedidos" (
  "id_pedido" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "dni_cliente" varchar(9) NOT NULL,
  "dni_empleado" varchar(9) NOT NULL,
  "fecha_pedido" date NOT NULL
);

CREATE TABLE "detalle_pedido" (
  "id_pedido" int NOT NULL,
  "id_producto" int NOT NULL,
  "cantidad" int NOT NULL,
  "precio_unitario" numeric(10,2) NOT NULL,
  PRIMARY KEY ("id_pedido", "id_producto")
);

CREATE TABLE "bonificacion" (
  "dni_cliente" varchar(9) NOT NULL,
  "anio" smallint NOT NULL,
  "mes" smallint NOT NULL,
  PRIMARY KEY ("dni_cliente", "anio", "mes")
);

CREATE TABLE "zona_producto" (
  "id_zona" int NOT NULL,
  "id_producto" int NOT NULL,
  "cantidad" int NOT NULL,
  PRIMARY KEY ("id_zona", "id_producto")
);

CREATE TABLE "realizar" (
  "id_zona" int NOT NULL,
  "id_tarea" int NOT NULL,
  "fecha" timestamp NOT NULL,
  "tiempo_real_minutos" numeric(7,2) NOT NULL,
  PRIMARY KEY ("id_zona", "id_tarea", "fecha")
);

CREATE UNIQUE INDEX "zonas_index_0" ON "zonas" ("id_vivero", "nombre");

CREATE UNIQUE INDEX "productos_index_1" ON "productos" ("tipo", "nombre");

ALTER TABLE "bonificacion"
ADD FOREIGN KEY ("dni_cliente")
REFERENCES "cliente_tajinaste_plus" ("dni_cliente");

ALTER TABLE "puestos"
ADD FOREIGN KEY ("dni_empleado")
REFERENCES "empleados" ("dni_empleado");

ALTER TABLE "puestos" ADD FOREIGN KEY ("id_vivero") REFERENCES "viveros" ("id_vivero");

ALTER TABLE "zonas" ADD FOREIGN KEY ("id_vivero") REFERENCES "viveros" ("id_vivero");

ALTER TABLE "tareas" ADD FOREIGN KEY ("id_puesto") REFERENCES "puestos" ("id_puesto");

ALTER TABLE "pedidos" ADD FOREIGN KEY ("dni_cliente") REFERENCES "cliente_tajinaste_plus" ("dni_cliente");

ALTER TABLE "pedidos" ADD FOREIGN KEY ("dni_empleado") REFERENCES "empleados" ("dni_empleado");

ALTER TABLE "detalle_pedido"
ADD FOREIGN KEY ("id_pedido")
REFERENCES "pedidos" ("id_pedido");

ALTER TABLE "detalle_pedido"
ADD FOREIGN KEY ("id_producto")
REFERENCES "productos" ("id_producto");

ALTER TABLE "zona_producto"
ADD FOREIGN KEY ("id_zona")
REFERENCES "zonas" ("id_zona");

ALTER TABLE "zona_producto"
ADD FOREIGN KEY ("id_producto")
REFERENCES "productos" ("id_producto");

ALTER TABLE "realizar" ADD FOREIGN KEY ("id_zona") REFERENCES "zonas" ("id_zona");

ALTER TABLE "realizar" ADD FOREIGN KEY ("id_tarea") REFERENCES "tareas" ("id_tarea");
